#include "stdafx.h"#include "HcdElementBase.h"#include <HcdMemoryService.h>#include <HcdDataTypes_.h>struct S8DO_P{#include "PrivateVars/8DO.h"};class K8DO : public KHcdElementBase  , protected S8DO_P{  W_8DO *m_pHardware;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _8DO("8DO", K8DO::Create);IHcdElement *K8DO::Create(){  return new K8DO;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( K8DO, 33 )void K8DO::InitParm(){#include "PrivateVars/8DO.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void K8DO::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  m_pHardware = (W_8DO*)KMemoryServiceHCD::Instance().IoCreateObj( szName, W_8DO::TypeID, domain );  m_pSharedObject = (BYTE*)m_pHardware;  m_pSharedVarsInfo = new SVarInfo[8];  AddSharedField( "RAW1", NULL, offsetof(W_8DO, W_8DO::RAW1), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW2", NULL, offsetof(W_8DO, W_8DO::RAW2), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW3", NULL, offsetof(W_8DO, W_8DO::RAW3), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW4", NULL, offsetof(W_8DO, W_8DO::RAW4), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW5", NULL, offsetof(W_8DO, W_8DO::RAW5), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW6", NULL, offsetof(W_8DO, W_8DO::RAW6), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW7", NULL, offsetof(W_8DO, W_8DO::RAW7), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW8", NULL, offsetof(W_8DO, W_8DO::RAW8), ehtBool, sizeof(tBool), 8 );  qsort( m_pSharedVarsInfo, m_kSharedVarsInfo, sizeof( SVarInfo ), CompVarInfo );}void K8DO::StepCalc( SStepCalcParams &params ){  tBool *pOUTRx = &OUTR0;  tBool *pINLx = &INL0;  tBool *pInvertx = &IC1;  tBool *pRawx = &m_pHardware->RAW1;  for( int i=0; i<8; ++i )  {    if( pInvertx[i] )      pOUTRx[i] = pINLx[i] ? 0 : 1;    else      pOUTRx[i] = pINLx[i];    pRawx[i] = pOUTRx[i];  }}